INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), 1, 'Phase 1: The Blank Page', 'Where to start', 'Five minutes of your own thinking before AI is worth more than an hour of editing AI''s output afterwards. Direction comes from you. Typing can come from anywhere.', 'This first scenario tests the single most important AI habit: whether the learner uses AI as a first replacement for thinking, or as a second pair of hands after their own thinking has started. It sets the tone for the rest of the simulator: the goal is not to use AI more or less, but to use it after your own direction is clear.');

