INSERT INTO component_mcq (question) VALUES ('You need to write a 500-word summary of a difficult project for your manager by tomorrow. It is 9 in the evening. You are tired. You could open a new document, or you could open an AI chat window. Where do you begin?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You need to write a 500-word summary of a difficult project for your manager by tomorrow. It is 9 in the evening. You are tired. You could open a new document, or you could open an AI chat window. Where do you begin?' ORDER BY id DESC LIMIT 1), 'You open the AI chat first and ask it to write the whole summary for you. You will edit later, but right now you just need something on the page.', 'Understandable at 9pm, but this is the pattern that quietly erodes self-sufficiency over time. When AI writes first, your own thinking never fully forms, and the edits you make later are shallow because you never held the structure in your head. There is a small middle path that costs almost nothing: 5 minutes of your own rough thoughts first.');
