INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You need to write a 500-word summary of a difficult project for your manager by tomorrow. It is 9 in the evening. You are tired. You could open a new document, or you could open an AI chat window. Where do you begin?' ORDER BY id DESC LIMIT 1), 'You spend 5 minutes writing a scrappy bullet-point outline of what you actually want to say. Then you paste it into the AI chat and ask it to help you turn it into a clean 500-word summary in your voice.', 'Excellent. Those 5 minutes are the most important minutes in the whole task. You held the direction, AI handled the typing. The output will sound like you because you gave it the raw material of your own thinking. This is exactly what healthy, effective AI use looks like.');
