INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You need to write a 500-word summary of a difficult project for your manager by tomorrow. It is 9 in the evening. You are tired. You could open a new document, or you could open an AI chat window. Where do you begin?' ORDER BY id DESC LIMIT 1), 'You refuse to use AI at all. Writing the whole thing yourself is the only way to keep your skills sharp.', 'This preserves autonomy fully but pays a real cost. You will spend two hours on a task that should take 45 minutes, and you will still send a tired 9pm summary. Self-sufficiency does not mean refusing tools. It means using them from a position of clarity, not from a position of dependence. The middle path in option 2 protects both your time and your voice.');
