INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), 2, 'Phase 2: The Confident Answer', 'Verify before you trust', 'AI is confident by default. That does not make it correct. Verify anything that would cost you real money, time, or reputation if it turned out to be wrong.', 'This scenario teaches the most important AI habit for cost-avoidance: verification. AI confidence is not correlated with correctness, and unverified AI answers on regulated topics are one of the most common ways women lose real money or make real mistakes. The goal is not fear, it is a calm verification habit.');

