INSERT INTO component_mcq (question) VALUES ('You ask an AI a specific question about Belgian tax rules for freelancers, because you are considering starting a small side project. The AI gives you a detailed, confident, professional-sounding answer with specific percentages, deadlines, and references to article numbers. What do you do next?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You ask an AI a specific question about Belgian tax rules for freelancers, because you are considering starting a small side project. The AI gives you a detailed, confident, professional-sounding answer with specific percentages, deadlines, and references to article numbers. What do you do next?' ORDER BY id DESC LIMIT 1), 'The answer looks professional and specific. You trust it and start planning your side project based on the numbers it gave you.', 'This is the single most common AI mistake. AI models are fluent by design; fluency and correctness are not the same thing. AI regularly invents specific numbers, dates, article references, and even whole citations that sound completely real. On something like tax rules, one wrong percentage can cost you thousands of euros and a stressful conversation with your accountant. Verify before you act.');
