INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You ask an AI a specific question about Belgian tax rules for freelancers, because you are considering starting a small side project. The AI gives you a detailed, confident, professional-sounding answer with specific percentages, deadlines, and references to article numbers. What do you do next?' ORDER BY id DESC LIMIT 1), 'You use the AI answer as a starting orientation only. You verify the specific numbers on the official FPS Finance / SPF Finances website, or check with an accountant, before making any decision.', 'This is exactly the right habit. AI is excellent for getting you oriented to a topic quickly, so you know what to ask and what to look up. It is not a substitute for official sources, especially on anything involving money, health, law, or your family''s specific situation. You treated AI as a junior colleague, not as an authority. That is the whole skill.');
