INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You ask an AI a specific question about Belgian tax rules for freelancers, because you are considering starting a small side project. The AI gives you a detailed, confident, professional-sounding answer with specific percentages, deadlines, and references to article numbers. What do you do next?' ORDER BY id DESC LIMIT 1), 'You reject the answer entirely and decide not to use AI for any factual questions in the future. It cannot be trusted.', 'Understandable but too broad. AI is genuinely useful for orientation, first drafts, and language work; the problem is not that it is untrustworthy, it is that you have to know which parts to trust. Complete avoidance leaves a lot of usefulness on the table. The right move is not distrust; it is verification.');
