INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), 3, 'Phase 3: The First Answer', 'Shaping the output', 'The first prompt is never the best one. The second prompt, where you correct, refine, or narrow, is where AI actually becomes useful.', 'This scenario tests whether the learner treats AI as a one-shot machine or as a collaborator that improves through iteration. The single biggest skill separating effective AI users from frustrated ones is the willingness to give a short, specific correction rather than accepting the first output or throwing it away.');

