INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You asked AI to help you draft a follow-up email to a potential client. The first answer comes back polished, but too formal, generic, and not quite in your voice. You need to send this in the next 20 minutes. What do you do?' ORDER BY id DESC LIMIT 1), 'You accept the first draft because you are short on time. It is not perfect but it is fine. You add your name and send it.', 'This is where most AI value is lost. The first prompt is almost never the best one; AI improves dramatically on the second and third pass. Sending the first draft means your client receives a message that sounds like every other AI-drafted email in their inbox. Two minutes of refinement would have made this genuinely useful.');
