INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You asked AI to help you draft a follow-up email to a potential client. The first answer comes back polished, but too formal, generic, and not quite in your voice. You need to send this in the next 20 minutes. What do you do?' ORDER BY id DESC LIMIT 1), 'You give AI a short, direct correction: ''This is too formal. Rewrite it warmer, shorter, in a conversational tone. Keep the main points but sound like a real person, not a corporate template.'' Then you make two small edits of your own and send.', 'Textbook. You just used AI the way it is designed to be used, as an iterative collaborator, not a one-shot generator. The correction was specific, the tone instruction was clear, and you kept the final edit in your own hands. This is where AI genuinely saves you time instead of just giving you something to fix.');
