INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You asked AI to help you draft a follow-up email to a potential client. The first answer comes back polished, but too formal, generic, and not quite in your voice. You need to send this in the next 20 minutes. What do you do?' ORDER BY id DESC LIMIT 1), 'You throw out the AI draft entirely and write the whole email yourself from scratch. If AI cannot get it right first time, it is not worth the trouble.', 'Understandable frustration, but this is the pattern that leaves most AI value on the table. AI is not meant to get things right on the first prompt; the second prompt is where the real usefulness lives. Discarding the whole draft means you did the hardest part (starting) twice. A single correcting sentence would have unlocked most of what you needed.');
