INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), 4, 'Phase 4: The Data Question', 'What to put in, what to keep out', 'The cost of AI is not the subscription. It is what happens to the data you paste in. Anonymise first; convenience second.', 'This scenario teaches the cost dimension most women learn about only after something goes wrong: what enters the AI chat is not always private. It reframes ''cost'' from subscription fees to something bigger, the real cost of data leakage, and teaches the specific habit of anonymising before pasting.');

-- Component 1 for Card 3
INSERT INTO component_text (content) VALUES ('A colleague is showing you a great new productivity trick: she drops confidential client documents into a free AI tool and asks it to summarise, translate, and analyse them. It is saving her hours. She suggests you do the same with your team''s internal reports. What do you do?');
INSERT INTO card_contains (card_id, component_type, component_order_index, component_id) VALUES ((SELECT id FROM card WHERE title = 'Phase 4: The Data Question' AND owner_id = (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use') LIMIT 1), 'text', 1, LAST_INSERT_ID());

-- Component 2 for Card 3
INSERT INTO component_mcq (question) VALUES ('A colleague is showing you a great new productivity trick: she drops confidential client documents into a free AI tool and asks it to summarise, translate, and analyse them. It is saving her hours. She suggests you do the same with your team''s internal reports. What do you do?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'A colleague is showing you a great new productivity trick: she drops confidential client documents into a free AI tool and asks it to summarise, translate, and analyse them. It is saving her hours. She suggests you do the same with your team''s internal reports. What do you do?' ORDER BY id DESC LIMIT 1), 'You follow her lead and start doing the same thing. If everyone is doing it, it must be fine. The time savings are enormous.', 'Convenience is real, but the cost is invisible until it is not. Free AI tools often use your data to train their models unless you have specifically opted out; some tools store and log your inputs indefinitely. Uploading client documents, internal reports, personal health information, or identifying details can breach GDPR, your employment contract, or your client agreements, without you ever knowing. The trick is to use AI for the summary structure, not on the confidential content itself.');
