INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'A colleague is showing you a great new productivity trick: she drops confidential client documents into a free AI tool and asks it to summarise, translate, and analyse them. It is saving her hours. She suggests you do the same with your team''s internal reports. What do you do?' ORDER BY id DESC LIMIT 1), 'You use AI for the same kind of work but only after removing all identifying details, client names, financial specifics, and confidential information. You paste in an anonymised or restructured version, then apply the AI''s help back to the original yourself.', 'This is exactly the right approach. You kept the productivity gain, and you kept your privacy, contractual, and legal integrity intact. It takes an extra 3 minutes and saves you from risks that only become visible when they explode. This is what cost-aware AI use looks like: the real cost is not the subscription fee, it is what happens when data leaves.');
