INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'A colleague is showing you a great new productivity trick: she drops confidential client documents into a free AI tool and asks it to summarise, translate, and analyse them. It is saving her hours. She suggests you do the same with your team''s internal reports. What do you do?' ORDER BY id DESC LIMIT 1), 'You decide not to use AI for work documents at all. It is safer to just do things the old way.', 'This protects privacy fully but pays a real productivity cost. There is a middle path: use AI on anonymised versions of your work, or use tools where your organisation has an enterprise agreement with proper data guarantees. Blanket avoidance leaves you falling further behind colleagues who are learning safe practical use.');
