INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), 5, 'Phase 5: The Late Night', 'When to use AI, and when not to', 'AI can help you find words. It cannot hold you. Use it as the pen, not as the ear.', 'This scenario teaches the most important boundary in healthy AI use: the difference between using AI as a thinking assistant and using it as an emotional substitute. Late nights are when this boundary matters most, and when women are most likely to blur it. The goal is neither total reliance nor total avoidance, but conscious use.');

-- Component 1 for Card 4
INSERT INTO component_text (content) VALUES ('It is 11pm. You had a difficult conversation with someone close to you earlier this evening. You are still upset. You are alone. Your AI chat window is open on your laptop, and you are considering typing everything out and asking it to help you make sense of what happened. What do you do?');
INSERT INTO card_contains (card_id, component_type, component_order_index, component_id) VALUES ((SELECT id FROM card WHERE title = 'Phase 5: The Late Night' AND owner_id = (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use') LIMIT 1), 'text', 1, LAST_INSERT_ID());

-- Component 2 for Card 4
INSERT INTO component_mcq (question) VALUES ('It is 11pm. You had a difficult conversation with someone close to you earlier this evening. You are still upset. You are alone. Your AI chat window is open on your laptop, and you are considering typing everything out and asking it to help you make sense of what happened. What do you do?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It is 11pm. You had a difficult conversation with someone close to you earlier this evening. You are still upset. You are alone. Your AI chat window is open on your laptop, and you are considering typing everything out and asking it to help you make sense of what happened. What do you do?' ORDER BY id DESC LIMIT 1), 'You type everything out in detail, share names and full context, and let the AI walk you through it all night. It feels patient and non-judgmental in a way people rarely are.', 'AI can genuinely help you organise your thoughts, and there is nothing wrong with using it for that. But there are three specific risks late at night: you tend to share more identifying details than you should, you can build an emotional dependency on a tool that cannot actually remember or care about you, and you skip the harder step of taking your real feelings to a person who knows you. AI can be the pen; a trusted person is the ear.');
