     AND option_text = 'You type everything out in detail, share names and full context, and let the AI walk you through it all night. It feels patient and non-judgmental in a way people rarely are.' 
     ORDER BY id DESC LIMIT 1), (SELECT id FROM simulator_metric WHERE name = 'Discernment' LIMIT 1), -15);
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It is 11pm. You had a difficult conversation with someone close to you earlier this evening. You are still upset. You are alone. Your AI chat window is open on your laptop, and you are considering typing everything out and asking it to help you make sense of what happened. What do you do?' ORDER BY id DESC LIMIT 1), 'You use AI only to help you organise your own thoughts, without identifying details, then close the laptop. You save the harder version of the conversation for tomorrow, with a friend, a partner, or a therapist who actually knows you.', 'This is exactly the right boundary. AI is very good at helping you find words when your feelings feel tangled; it is not a substitute for someone who has known you for years. You used the tool for what it does well and stopped where it stops being useful. That is healthy emotional autonomy in action.');
