INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It is 11pm. You had a difficult conversation with someone close to you earlier this evening. You are still upset. You are alone. Your AI chat window is open on your laptop, and you are considering typing everything out and asking it to help you make sense of what happened. What do you do?' ORDER BY id DESC LIMIT 1), 'You close the laptop without typing anything. AI is for work, not for feelings. You will manage tonight on your own.', 'This protects the emotional boundary fully, which is worth something. But AI can genuinely help you think more clearly when your head is spinning, without any real emotional cost, if you keep the boundaries in place. Refusing to use it for anything personal is overcorrecting. The middle path in option 2 uses the tool where it helps and stops where it does not.');
