INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), 6, 'Phase 6: The Almost-Ready Draft', 'Who wrote this?', 'A good AI user leaves every conversation still sounding like herself. The polish is not the point. The voice is.', 'This final scenario tests the deepest healthy-use skill: keeping your voice intact even when AI''s default voice sounds polished. It closes the simulator on the point that matters most, effective AI use is not about how much you rely on AI, it is about how much of you remains in the final output.');

-- Component 1 for Card 5
INSERT INTO component_text (content) VALUES ('You asked AI to write a personal introduction paragraph for your new professional profile. The output is polished, well-structured, and technically correct. But when you read it back to yourself, it does not really sound like you, it sounds like a version of you written by a stranger. What do you do?');
INSERT INTO card_contains (card_id, component_type, component_order_index, component_id) VALUES ((SELECT id FROM card WHERE title = 'Phase 6: The Almost-Ready Draft' AND owner_id = (SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use') LIMIT 1), 'text', 1, LAST_INSERT_ID());

