INSERT INTO component_mcq (question) VALUES ('You asked AI to write a personal introduction paragraph for your new professional profile. The output is polished, well-structured, and technically correct. But when you read it back to yourself, it does not really sound like you, it sounds like a version of you written by a stranger. What do you do?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You asked AI to write a personal introduction paragraph for your new professional profile. The output is polished, well-structured, and technically correct. But when you read it back to yourself, it does not really sound like you, it sounds like a version of you written by a stranger. What do you do?' ORDER BY id DESC LIMIT 1), 'You copy and paste the AI text into your profile as-is. It sounds professional, that is what matters. Your voice is not that different anyway.', 'This is the pattern that quietly makes people sound the same across the internet. Your voice is one of the few things that actually distinguishes you professionally; AI''s default voice is generic on purpose. Pasting AI-as-is into anything public gives up something small each time, until eventually your online presence sounds like everyone else''s. The polish is not the point; the sound of you is.');
