INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You asked AI to write a personal introduction paragraph for your new professional profile. The output is polished, well-structured, and technically correct. But when you read it back to yourself, it does not really sound like you, it sounds like a version of you written by a stranger. What do you do?' ORDER BY id DESC LIMIT 1), 'You keep the structure AI gave you, then rewrite roughly half of the sentences in your own words, changing at least three specific phrases that felt too corporate or too generic. You end with your version, not the AI''s.', 'This is exactly the right balance. You kept the time-saving structural work AI did well, and you kept the part that matters most, the actual voice on the page. This is what healthy AI use produces: text that could not have existed without you, only faster. Your voice stayed intact.');
