INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You asked AI to write a personal introduction paragraph for your new professional profile. The output is polished, well-structured, and technically correct. But when you read it back to yourself, it does not really sound like you, it sounds like a version of you written by a stranger. What do you do?' ORDER BY id DESC LIMIT 1), 'You throw out the AI draft entirely and write the whole thing from scratch. Only your own words are worth putting on a professional profile.', 'This preserves your voice fully but pays a time cost that was probably unnecessary. The structural work AI did (paragraph flow, sentence variety, opening line) is not the part of you that needed to stay untouched. Editing something halfway there is often better and faster than starting again. The middle path in option 2 gives you both.');
