-- Feedback for metric 'Autonomy' (Score 0-49)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Autonomy' LIMIT 1), 0, 49, 'You are curious about AI and willing to try new tools. That openness is a real starting point.', 'You tend to reach for AI before your own thinking has started. Over time this can quietly erode your writing voice, decision-making confidence, and sense that you can figure things out on your own.', 'For the next three tasks, spend 5 minutes on your own scrappy notes before opening AI. Even if the notes feel bad, keep them, then hand them to AI for shaping.', NULL, 'When autonomy is low, AI can silently take over the work your own thinking was meant to do. The A Brief Use of AI course gives you the specific practice of starting with your own rough thoughts first, so the AI''s output stays anchored to your voice and direction, not to a generic default.');

-- Feedback for metric 'Autonomy' (Score 50-85)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Autonomy' LIMIT 1), 50, 85, 'You use AI as a collaborator, not a replacement. Your own thinking still leads the work.', 'You still let AI take over on high-effort or late-night tasks, when your own thinking would have added more value with a small extra investment of time.', 'Notice one moment this week when you reach for AI out of tiredness rather than genuine need. Try 5 minutes of your own notes first, and see what changes.', NULL, 'You already have a working relationship with AI. The next step is protecting that relationship in the moments you are most vulnerable to over-reliance, tiredness, emotional moments, high-pressure deadlines. The A Brief Use of AI course teaches the four boundaries that keep AI a tool in your hand instead of a hand you have quietly handed over.');

-- Feedback for metric 'Autonomy' (Score 85-100)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Autonomy' LIMIT 1), 85, 100, 'You use AI often and still sound like yourself. Your voice, judgement, and human relationships are intact.', 'None. Just watch that your autonomy stays paired with practical use, avoiding AI entirely is not a mark of independence, it is a different cost.', 'Teach one woman in your life how to keep her voice when using AI. Show her one specific trick that works for you.', NULL, 'Autonomy in AI use is one of the most valuable skills you can pass on. The A Brief Use of AI course helps you articulate the practices you are already doing intuitively, so you can teach them to others and continue refining them in higher-stakes contexts where the boundary between helpful and harmful use gets subtler.');

-- Feedback for metric 'Effectiveness' (Score 0-49)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Effectiveness' LIMIT 1), 0, 49, 'You approach AI honestly, without pretending to know things you do not know. That honesty is a genuine strength.', 'You often accept the first AI answer as final, or discard it entirely when it disappoints. The most valuable part of AI use, iterative refinement, is where you are leaving the most value on the table.', 'The next time an AI answer disappoints you, do not delete it. Instead, write one specific correction (''shorter'', ''warmer'', ''in my voice'', ''more concrete''). See what the second answer becomes.', NULL, 'When effectiveness is low, the missing skill is almost always the same: prompt iteration. The A Brief Use of AI course teaches copy-ready prompts across work, home, and learning, plus the specific technique of correcting the first answer with a short direct instruction, the single practice that separates frustrated AI users from effective ones.');

-- Feedback for metric 'Effectiveness' (Score 50-85)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Effectiveness' LIMIT 1), 50, 85, 'You know how to give AI useful direction, and you iterate when the first answer is not quite right.', 'You still sometimes accept mediocre outputs when a small correction would unlock a much better version. You also sometimes forget to give AI enough context up front, which slows down the whole exchange.', 'Next time you write a prompt, add one sentence of context up front: who you are, what you are trying to achieve, and what tone or format you want. That one sentence often replaces three rounds of correction.', NULL, 'You have the core iteration skill already. The next step is upfront prompt clarity, giving AI enough context in the first message so the second round of correction is smaller. The A Brief Use of AI course walks through the specific ways to frame prompts for different kinds of tasks, so you get useful output faster and with less back-and-forth.');

-- Feedback for metric 'Effectiveness' (Score 85-100)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Effectiveness' LIMIT 1), 85, 100, 'You get real, useful, voice-specific output from AI reliably. You know how to iterate, correct, and reshape.', 'None. Just watch that effectiveness does not tip into automation, the moments where you let AI do everything because it can, not because it should.', 'Pick one task this week that AI could technically do for you, but which is worth doing yourself for the practice or the ownership. Do that one by hand.', NULL, 'High effectiveness with AI is a rare and valuable capacity. The A Brief Use of AI course helps you deepen the strategic side of that capacity, knowing when to reach for AI and when to consciously not, so your effectiveness stays paired with judgement and does not become mere convenience.');

-- Feedback for metric 'Discernment' (Score 0-49)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Discernment' LIMIT 1), 0, 49, 'You are trusting and open to new tools, which is what makes learning possible in the first place.', 'You tend to accept AI answers without verifying, share more personal or confidential information than is safe, or reach for AI even when the task calls for something else (an official source, a human, silence). The cost of these habits is invisible until it is not.', 'Before your next AI conversation, ask yourself one question: ''if this answer were wrong, what would it cost me?'' If the answer is significant, plan to verify.', NULL, 'When discernment is low, small AI habits carry outsized risk: unverified facts, leaked data, wrong tool for the moment. The A Brief Use of AI course gives you the 3-step verification habit, the four healthy boundaries, and the specific test of when AI is the right tool and when it is not, all in about 15 minutes.');

-- Feedback for metric 'Discernment' (Score 50-85)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Discernment' LIMIT 1), 50, 85, 'You verify AI on important facts, and you generally know what to share and what not to.', 'You still sometimes get caught out on lower-stakes tasks, small factual claims you did not double-check, casual pasting of details you should have anonymised, using AI for things a quick search or a trusted colleague would have answered better.', 'Before pasting anything into AI this week, do one sanity check: ''would I be comfortable if this appeared publicly?'' If the answer is no, anonymise or restructure first.', NULL, 'You have working discernment on the biggest calls. The next step is applying the same care to the smaller, more frequent decisions where risk accumulates. The A Brief Use of AI course helps you build fast, everyday habits for privacy, verification, and picking the right tool, so discernment becomes automatic rather than effortful.');

-- Feedback for metric 'Discernment' (Score 85-100)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'AI in Your Hands: Healthy, Practical, Self-Sufficient Use'), (SELECT id FROM simulator_metric WHERE name = 'Discernment' LIMIT 1), 85, 100, 'You know when to use AI, when to verify, when to anonymise, and when to reach for something else entirely.', 'None. Just watch that discernment does not tip into over-caution, spending more time checking than the task warrants is its own kind of cost.', 'Share one specific verification habit with a colleague or friend who is newer to AI. Your instincts are the kind of thing most people learn only after making a mistake.', NULL, 'Strong discernment is one of the rarest AI skills, most people either trust too much or too little. The A Brief Use of AI course helps you refine and articulate the decision-making rules you are already applying, so you can teach them to others and continue calibrating them as AI tools change over the next few years.');

